// Browser-local shop directory and transaction history. Legacy records keep unknown dates.
let invoiceQuery='',invoiceDate='',shopQuery='';
function businessDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function normalizeText(value){return String(value||'').normalize('NFKC').replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c)).trim().toLowerCase()}
function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const d=new Date(value+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===value}
function upgradeData(data,fresh=false){
  data.customers??=[];data.sales??=[];data.purchases??=[];data.receipts??=[];
  const used=new Set(data.customers.map(c=>normalizeText(c.code)).filter(Boolean));
  for(const c of data.customers){if(!c.code){let code='SHOP-'+String(c.id).padStart(3,'0');while(used.has(normalizeText(code)))code+='A';c.code=code;used.add(normalizeText(code))}c.owner??='';c.address??='';c.email??='';}
  if(fresh){data.customers.push({id:4,bn:'রানা ভাই',en:'Rana Bhai',owner:'রানা',phone:'01700-000004',code:'RANA-1',address:'মিরপুর, ঢাকা',email:'',due:0},{id:5,bn:'ভাই ভাই স্টোর',en:'Bhai Bhai Store',owner:'জামাল',phone:'01700-000005',code:'BHAI-1',address:'মিরপুর, ঢাকা',email:'',due:0});for(const c of data.customers){if(!c.owner)c.owner=c.bn;if(!c.address)c.address='মিরপুর, ঢাকা'}for(const s of data.sales)s.date=businessDate();}
  // Never infer dates for existing records that did not record one.
  data.schemaVersion=2;return data;
}
function shopSnapshot(id){const c=db.customers.find(c=>c.id===Number(id));return c?{bn:c.bn,en:c.en,code:c.code,owner:c.owner,phone:c.phone,address:c.address}:null}
function shopFields(record){return record.shopSnapshot||db.customers.find(c=>c.id===Number(record.shopId??record.customer))||{bn:typeof record.customer==='string'?record.customer:'নগদ ক্রেতা',en:typeof record.customer==='string'?record.customer:'Walk-in customer',code:''}}
function displayDate(date){return validDate(date)?new Date(date+'T12:00:00Z').toLocaleDateString(lang==='bn'?'bn-BD':'en-GB',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Dhaka'}):t('তারিখ সংরক্ষিত নেই','Date not recorded')}
function shops(){return head(t('দোকানদারের তালিকা','Shop directory'),t('দোকানের নাম বা কোড দিয়ে খুঁজুন। বিস্তারিত দেখতে নামে চাপুন।','Search by shop name or code. Select a name to view details.'),`<div class="row wrap">${btn(t('পণ্য যোগ করুন','Add product'),'onclick="addProduct()"',false)}${btn(t('নতুন দোকান যোগ করুন','Add shop'),'onclick="shopForm()"',true)}</div>`)+`<section class="panel"><div class="toolbar"><input id="shop-search" aria-label="${t('দোকানের নাম বা কোড','Shop name or code')}" placeholder="${t('দোকানের নাম / কোড খুঁজুন','Search shop name / code')}" value="${esc(shopQuery)}" oninput="shopQuery=this.value;renderShopRows()"></div><div id="shop-rows">${shopRows()}</div></section>`}
function shopRows(){const q=normalizeText(shopQuery),rows=db.customers.filter(c=>!c.archivedAt&&normalizeText(c.bn+' '+c.en+' '+c.code).includes(q));if(!rows.length)return `<div class="empty">${t('কোনো দোকান পাওয়া যায়নি। নতুন দোকান যোগ করুন অথবা খোঁজ বদলান।','No shops found. Add a shop or change your search.')}</div>`;return `<div class="tablewrap" tabindex="0" role="region" aria-label="${t('দোকানের তালিকা; পাশে স্ক্রল করুন','Shop list; scroll horizontally')}"><table><thead><tr><th>${t('দোকানের নাম','Shop name')}</th><th>${t('কোড','Code')}</th><th>${t('মালিক','Owner')}</th><th>${t('বিক্রি','Sales')}</th><th>${t('কেনাকাটা','Purchases')}</th><th>${t('বাকি','Customer due')}</th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="shop-name" onclick="shopDetail(${c.id})">${name(c)} ${icon('arrow')}</button></td><td>${esc(c.code)}</td><td>${esc(c.owner)||'—'}</td><td>${money(db.sales.filter(s=>s.customer===c.id).reduce((n,s)=>n+s.total,0))}</td><td>${money(db.purchases.filter(p=>(p.shopId??p.customer)===c.id).reduce((n,p)=>n+p.total,0))}</td><td>${money(c.due)}</td></tr>`).join('')}</tbody></table></div>`}
function renderShopRows(){document.querySelector('#shop-rows').innerHTML=shopRows()}
function shopDetail(id){const c=db.customers.find(c=>c.id===id);if(!c)return;show(`<h2>${name(c)}</h2><span class="tag">${esc(c.code)}</span><dl class="shop-details"><dt>${t('মালিকের নাম','Owner')}</dt><dd>${esc(c.owner)||'—'}</dd><dt>${t('মোবাইল নম্বর','Mobile number')}</dt><dd>${esc(c.phone)||'—'}</dd><dt>${t('ঠিকানা','Address')}</dt><dd>${esc(c.address)||t('যোগ করা হয়নি','Not provided')}</dd><dt>${t('ইমেইল','Email')}</dt><dd>${esc(c.email)||'—'}</dd><dt>${t('ক্রেতার বাকি','Customer due')}</dt><dd>${money(c.due)}</dd></dl><div class="row wrap"><button class="btn" onclick="closeDialog()">${t('ফিরে যান','Back')}</button><button class="btn" onclick="shopForm(${id})">${t('সম্পাদনা করুন','Edit')}</button><button class="btn danger" onclick="confirmShopDelete(${id})">${t('মুছে ফেলুন','Delete')}</button><button class="btn primary" onclick="closeDialog();invoiceQuery=${esc(JSON.stringify(c.code))};invoiceDate='';navigate('invoice')">${t('লেনদেন দেখুন','View transactions')}</button></div>`)}
function shopForm(id=null){const c=id?db.customers.find(c=>c.id===id):{};if(!c)return;const fields=[['shopName',t('দোকানের নাম','Shop name'),c.bn||'','text',true],['owner',t('মালিকের নাম','Owner name'),c.owner||'','text',true],['phone',t('মোবাইল নম্বর','Mobile number'),c.phone||'','tel',true],['code',t('দোকান কোড','Shop code'),c.code||'','text',true],['address',t('ঠিকানা (ঐচ্ছিক)','Address (optional)'),c.address||'','text',false],['email',t('ইমেইল (ঐচ্ছিক)','Email (optional)'),c.email||'','email',false]];show(`<h2>${id?t('দোকানের তথ্য সম্পাদনা','Edit shop'):t('নতুন দোকান যোগ করুন','Add a shop')}</h2><form onsubmit="saveShop(event,${id})">${fields.map(([key,label,value,type,required])=>`<div class="field"><label for="shop-${key}">${label}</label><input id="shop-${key}" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="${key==='address'?250:100}" ${key==='phone'?'inputmode="tel"':''}></div>`).join('')}<p class="error" id="shop-error" role="alert"></p><div class="row wrap"><button type="button" class="btn" onclick="${id?`shopDetail(${id})`:'closeDialog()'}">${t('ফিরে যান','Back')}</button><button class="btn primary">${t('সংরক্ষণ করুন','Save')}</button></div></form>`)}
function validateShop(values,id=null){if(!values.shopName||!values.owner||!values.phone||!values.code)return t('দোকানের নাম, মালিকের নাম, মোবাইল ও কোড দিন।','Enter shop name, owner, mobile and code.');const phone=normalizeText(values.phone).replace(/[\s()-]/g,'');if(!/^(?:\+?880|0)1[3-9]\d{8}$/.test(phone))return t('সঠিক বাংলাদেশি মোবাইল নম্বর দিন।','Enter a valid Bangladesh mobile number.');if(!/^[\p{L}\p{N}_-]{1,32}$/u.test(values.code))return t('কোডে সর্বোচ্চ ৩২টি অক্ষর, সংখ্যা, - বা _ ব্যবহার করুন।','Use up to 32 letters, numbers, - or _ in the code.');if(db.customers.some(c=>c.id!==id&&normalizeText(c.code)===normalizeText(values.code)))return t('এই কোডটি আগে ব্যবহার হয়েছে। অন্য কোড দিন।','That code is already in use. Choose another.');if(values.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email))return t('সঠিক ইমেইল দিন অথবা ঘরটি খালি রাখুন।','Enter a valid email or leave it empty.');return ''}
function saveShop(event,id=null){event.preventDefault();const f=new FormData(event.target),values=Object.fromEntries(['shopName','owner','phone','code','address','email'].map(k=>[k,String(f.get(k)||'').trim()]));const error=validateShop(values,id);if(error){document.querySelector('#shop-error').textContent=error;return}let c=id?db.customers.find(c=>c.id===id):null;if(id&&!c)return;if(!c){c={id:Math.max(0,...db.customers.map(c=>c.id))+1,due:0};db.customers.push(c)}else{for(const r of [...db.sales,...db.purchases,...db.receipts])if(Number(r.shopId??r.customer)===id&&!r.shopSnapshot)r.shopSnapshot=shopSnapshot(id)}Object.assign(c,{bn:values.shopName,en:values.shopName,owner:values.owner,phone:values.phone,code:values.code,address:values.address,email:values.email});save();closeDialog();render();toast(t('দোকানের তথ্য সংরক্ষিত','Shop saved'))}
function confirmShopDelete(id){const c=db.customers.find(c=>c.id===id);if(!c)return;show(`<h2>${t('দোকান মুছে ফেলবেন?','Delete this shop?')}</h2><p><b>${name(c)}</b> · ${esc(c.code)}</p><p>${t('দোকানটি সক্রিয় তালিকা থেকে সরবে। আগের লেনদেন ও বাকি মুছবে না; ইনভয়েসে পাওয়া যাবে।','The shop will leave the active list. Past transactions and dues will remain available in history.')}</p><div class="row wrap"><button class="btn" onclick="shopDetail(${id})">${t('বাতিল করুন','Cancel')}</button><button class="btn danger" onclick="deleteShop(${id})">${t('মুছে ফেলুন','Delete')}</button></div>`)}
function deleteShop(id){const c=db.customers.find(c=>c.id===id);if(!c||c.archivedAt)return;for(const r of [...db.sales,...db.purchases,...db.receipts])if(Number(r.shopId??r.customer)===id&&!r.shopSnapshot)r.shopSnapshot=shopSnapshot(id);c.archivedAt=new Date().toISOString();save();closeDialog();render();toast(t('দোকানটি তালিকা থেকে সরানো হয়েছে','Shop removed from active list'))}
function allTransactions(){return [...db.sales.map((r,index)=>({kind:'sale',index,r,amount:r.total,paid:r.paid,ref:'INV-'+r.id})),...db.purchases.map((r,index)=>({kind:'purchase',index,r,amount:r.total,paid:r.paid,ref:'PUR-'+(index+1)})),...db.receipts.map((r,index)=>({kind:'payment',index,r,amount:r.amount,paid:r.amount,ref:'PAY-'+(index+1)}))].sort((a,b)=>(b.r.date||'').localeCompare(a.r.date||'')||(b.r.time||'').localeCompare(a.r.time||''))}
function filteredTransactions(){const q=normalizeText(invoiceQuery);return allTransactions().filter(x=>{const s=shopFields(x.r),current=db.customers.find(c=>c.id===Number(x.r.shopId??x.r.customer)),hay=normalizeText([s.bn,s.en,s.code,current?.bn,current?.en,current?.code].join(' '));return (!q||hay.includes(q))&&(!invoiceDate||x.r.date===invoiceDate)})}
function kindLabel(k){return k==='sale'?t('বিক্রি','Sale'):k==='purchase'?t('কেনাকাটা','Purchase'):t('বাকি আদায়','Payment received')}
function invoices(){return head(t('ইনভয়েস ও লেনদেন','Invoices & transactions'),t('দোকানের নাম/কোড, তারিখ, অথবা দুটো দিয়েই হিসাব দেখুন।','Filter by shop name/code, date, or both.'))+`<section class="panel"><div class="invoice-filters"><div class="field"><label for="invoice-shop">${t('দোকানের নাম / কোড','Shop name / code')}</label><input id="invoice-shop" list="invoice-shops" value="${esc(invoiceQuery)}" placeholder="${t('সব দোকান — নাম বা কোড লিখুন','All shops — type a name or code')}" oninput="invoiceQuery=this.value;refreshInvoices()"><datalist id="invoice-shops">${db.customers.map(c=>`<option value="${esc(c.code)}">${name(c)}${c.archivedAt?t(' (তালিকা থেকে সরানো)',' (removed)'):''}</option>`).join('')}</datalist></div><div class="field"><label for="invoice-date">${t('ক্যালেন্ডার / তারিখ','Calendar / date')}</label><input id="invoice-date" type="date" value="${esc(invoiceDate)}" onchange="invoiceDate=this.value;refreshInvoices()"></div><button class="btn" onclick="invoiceQuery='';invoiceDate='';render()">${t('ফিল্টার মুছুন','Clear filters')}</button></div><p class="notice">${t('শুধু তারিখ → সেই দিনের সব দোকান। শুধু দোকান → সব তারিখ। দোকান + তারিখ → সেই দোকানের নির্দিষ্ট দিনের লেনদেন।','Date only → all shops on that date. Shop only → all dates. Shop + date → that shop’s transactions on the selected date.')}</p><div id="invoice-results">${invoiceResults()}</div></section>`}
function invoiceResults(){const list=filteredTransactions();return `<div class="transaction-summary" aria-live="polite"><b>${num(list.length)} ${t('টি লেনদেন','transactions')}</b><span>${t('বিক্রি','Sales')}: ${money(list.filter(x=>x.kind==='sale').reduce((s,x)=>s+x.amount,0))}</span><span>${t('কেনাকাটা','Purchases')}: ${money(list.filter(x=>x.kind==='purchase').reduce((s,x)=>s+x.amount,0))}</span><span>${t('বাকি আদায়','Collections')}: ${money(list.filter(x=>x.kind==='payment').reduce((s,x)=>s+x.amount,0))}</span></div>${allTransactions().some(x=>!validDate(x.r.date))?`<p class="muted">${t('কিছু পুরোনো লেনদেনে তারিখ নেই। তারিখের ফিল্টার সরালে সেগুলোও দেখা যাবে।','Some older records have no saved date. Clear the date filter to include them.')}</p>`:''}${!list.length?`<div class="empty">${t('এই দোকান/তারিখে কোনো লেনদেন পাওয়া যায়নি। ফিল্টার বদলান অথবা মুছে দিন।','No transactions match this shop/date. Change or clear the filters.')}</div>`:`<div class="tablewrap" tabindex="0" role="region" aria-label="${t('লেনদেনের তালিকা; পাশে স্ক্রল করুন','Transactions; scroll horizontally')}"><table><thead><tr><th>${t('দোকানের নাম / কোড','Shop / code')}</th><th>${t('তারিখ','Date')}</th><th>${t('ধরন / নম্বর','Type / reference')}</th><th>${t('টাকা','Amount')}</th><th>${t('বর্তমান বাকি','Current due')}</th><th>${t('বিস্তারিত','Details')}</th></tr></thead><tbody>${list.map(x=>{const s=shopFields(x.r);return `<tr><td><b>${name(s)}</b><small>${esc(s.code||'—')}</small></td><td>${displayDate(x.r.date)}<small>${esc(x.r.time||'')}</small></td><td>${kindLabel(x.kind)}<small>${esc(x.ref)}</small></td><td>${money(x.amount)}</td><td>${x.kind==='payment'?'—':money(x.amount-x.paid)}</td><td><button class="link" onclick="transactionDetail('${x.kind}',${x.index})">${t('বিস্তারিত দেখুন','View details')} ↗</button></td></tr>`}).join('')}</tbody></table></div>`}`}
function refreshInvoices(){document.querySelector('#invoice-results').innerHTML=invoiceResults()}
function invoice(id){const index=db.sales.findIndex(s=>s.id===id);if(index>=0)transactionDetail('sale',index)}
function transactionDetail(kind,index){const list=kind==='sale'?db.sales:kind==='purchase'?db.purchases:kind==='payment'?db.receipts:null;const r=list?.[index];if(!r)return;const s=shopFields(r),items=kind==='sale'?r.items:kind==='purchase'?r.lineItems||[]:[],amount=kind==='payment'?r.amount:r.total,paid=kind==='payment'?r.amount:r.paid;show(`<span class="tag">${t('ডেমো','DEMO')} · ${kindLabel(kind)}</span><h2 style="margin-top:16px">${name(s)}</h2><p>${esc(s.code||'—')} · ${displayDate(r.date)} ${esc(r.time||'')}</p>${kind==='sale'?`<b>INV-${r.id}</b>`:''}<div class="receipt">${items.map(i=>`<div class="row between wrap"><span>${esc(lang==='bn'?i.bn:i.name)}<small class="muted" style="display:block">${num(i.qty)} ${esc(i.unit)} × ${money(i.price)}</small></span><b>${money(i.qty*i.price)}</b></div>`).join('')}${kind==='purchase'&&!items.length?`<p>${t('পুরোনো ক্রয়ের পণ্যের মূল্য সংরক্ষিত নেই।','Item price snapshots were not recorded for this older purchase.')}</p>`:''}${kind==='payment'?`<p>${t('এটি বাকি আদায়ের রসিদ; নতুন পণ্য বিক্রি নয়।','This is a payment receipt, not a new product sale.')}</p>`:''}<div class="row between"><b>${t('মোট টাকা','Total amount')}</b><b>${money(amount)}</b></div>${kind!=='payment'?`<div class="row between"><span>${t('বর্তমানে পরিশোধিত','Currently paid')}</span><b>${money(paid)}</b></div><div class="row between"><span>${t('বর্তমান বাকি','Current due')}</span><b>${money(amount-paid)}</b></div>`:''}</div><div class="row wrap no-print"><button class="btn" onclick="closeDialog()">${t('ফিরে যান','Back')}</button><button class="btn primary" onclick="window.print()">${t('প্রিন্ট / PDF','Print / PDF')}</button></div>`)}
